{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--muted:#6b7280;--accent:#6b9b7a;--accent-2:#7aa6c7;--ink:#0f1724;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial,sans-serif;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,var(--card),transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:30;border-bottom:1px solid rgba(15,23,36,0.04)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-size:14px}
    nav a.cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px}
    main{max-width:980px;margin:36px auto;padding:0 22px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .kicker{display:inline-block;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;padding:6px 10px;border-radius:999px;font-size:13px}
    h1{margin:0 0 6px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted);font-size:15px}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:26px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 22px rgba(11,15,20,0.04);border:1px solid rgba(11,15,20,0.03);opacity:0;transform:translateY(18px);transition:opacity .6s ease,var(--transform) .6s ease}
    .card.reveal{opacity:1;transform:none}
    .card h3{margin:0 0 8px 0}
    .meta{color:var(--muted);font-size:13px}
    .pill{display:inline-block;background:linear-gradient(90deg,rgba(107,155,122,0.12),rgba(122,166,199,0.12));padding:6px 8px;border-radius:999px;font-size:12px;color:var(--muted)}
    .services-list{display:flex;flex-direction:column;gap:12px}
    .service-row{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;border:1px dashed rgba(11,15,20,0.04)}
    .service-info{max-width:76%}
    .price{color:var(--accent);font-weight:700}
    .small{font-size:13px;color:var(--muted)}
    footer{margin:46px 0 120px 0;text-align:center;color:var(--muted)}
    /* Session Planner */
    .planner{background:linear-gradient(180deg,rgba(122,166,199,0.06),rgba(107,155,122,0.03));padding:16px;border-radius:12px}
    .row{display:flex;gap:10px;align-items:center;margin:8px 0}
    label{min-width:120px;font-size:13px;color:var(--muted)}
    input[type=text],select,textarea{flex:1;padding:8px;border-radius:8px;border:1px solid rgba(11,15,20,0.06);background:white}
    button{background:var(--accent);border:0;color:white;padding:10px 12px;border-radius:10px;cursor:pointer}
    .muted-small{font-size:12px;color:var(--muted)}
    .actions{display:flex;gap:8px;align-items:center;margin-top:12px}
    .copyline{background:#fff;padding:12px;border-radius:8px;border:1px solid rgba(11,15,20,0.04);font-family:monospace;font-size:13px}
    /* decorative */
    .pattern{position:fixed;right:-120px;top:-80px;opacity:0.12;pointer-events:none}
    @media(max-width:720px){.grid{grid-template-columns:1fr}.brand{gap:8px}.logo{width:44px;height:44px}}
  </style>
</head>
<body>
  <svg class="pattern" width="420" height="420" viewBox="0 0 420 420" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <pattern id="p1" x="0" y="0" width="48" height="48" patternUnits="userSpaceOnUse">
        <rect width="24" height="24" fill="#f7fbf9"/>
        <circle cx="12" cy="12" r="3" fill="#7aa6c7"/>
      </pattern>
    </defs>
    <rect width="420" height="420" fill="url(#p1)"/>
  </svg>

  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Gentle, practical integrative care — cohort format</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Essentials</a>
      <a href="services.html">Services & Tracks</a>
      <a href="conditions.html">Health Notes</a>
      <a href="approach.html">How We Work</a>
      <a href="pricing.html">Investment</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <span class="kicker">Programs in cohorts</span>
      <h1>Practical tracks for steady change</h1>
      <p class="lead">Choose a guided group experience that meets weekly, blends teaching with peer support, and translates clear steps into everyday shifts. Ideal for people who want structure, accountability, and real-world tools.</p>
    </section>

    <section class="grid" id="offerings">
      <article class="card" data-reveal>
        <h3>Vital Thread — 8-week cohort</h3>
        <div class="meta">A gentle rewrite of daily habits: sleep anchors, meal patterns, rhythm-based movement.</div>
        <div style="margin-top:10px" class="small"><span class="pill">Group + weekly labs</span> • <span class="price">Suggested contribution: $320</span></div>
      </article>

      <article class="card" data-reveal>
        <h3>Roots & Rhythm — 12-week deep track</h3>
        <div class="meta">For recurring patterns like digestive sensitivity, persistent fatigue, and nervous system dysregulation.</div>
        <div style="margin-top:10px" class="small"><span class="pill">Cohort + optional 1:1</span> • <span class="price">Range-based support; sliding scale available</span></div>
      </article>

      <article class="card" data-reveal>
        <h3>Weekend Reset — 2-session mini-cohort</h3>
        <div class="meta">Short, practical reset with templates you can use immediately — movement, food, and rest cues.</div>
        <div style="margin-top:10px" class="small"><span class="pill">Hands-on, focused</span> • <span class="price">Pay-what-you-can model</span></div>
      </article>

      <article class="card" data-reveal>
        <h3>Custom Pathway — longer-term guidance</h3>
        <div class="meta">When your story doesn't fit a template. Small cohort size with personalized check-ins.</div>
        <div style="margin-top:10px" class="small"><span class="pill">Adaptable schedule</span> • <span class="price">Cohort contribution + optional private sessions</span></div>
      </article>
    </section>

    <section style="margin-top:28px">
      <h2 style="margin:0 0 8px 0">Session Planner</h2>
      <p class="muted-small" style="margin:0 0 12px 0">Build a short, exportable plan you can bring to orientation or your first cohort intake.</p>
      <div class="planner card" id="planner">
        <div class="row"><label for="name">Your name</label><input id="name" type="text" placeholder="First name"/></div>
        <div class="row"><label for="focus">Primary focus</label>
          <select id="focus">
            <option>Better sleep</option>
            <option>Digestive ease</option>
            <option>Energy / fatigue</option>
            <option>Stress & reactivity</option>
            <option>Hormone rhythm</option>
          </select>
        </div>
        <div class="row"><label for="symptoms">Key concerns</label><input id="symptoms" type="text" placeholder="e.g. bloating, afternoon crash, trouble falling asleep"/></div>
        <div class="row"><label for="time">Weekly time</label>
          <select id="time">
            <option>1–2 hours</option>
            <option>3–5 hours</option>
            <option>5+ hours</option>
          </select>
        </div>
        <div class="row"><label for="style">Preferred emphasis</label>
          <select id="style">
            <option>Food & digestion</option>
            <option>Movement & routines</option>
            <option>Stress skills & breathing</option>
            <option>Sleep & rest hygiene</option>
          </select>
        </div>
        <div class="actions">
          <button id="build">Compose plan</button>
          <button id="download" style="background:var(--accent-2)">Download .txt</button>
          <button id="copy" style="background:#444">Copy summary</button>
        </div>
        <div style="margin-top:12px">
          <div class="copyline" id="summary" aria-live="polite">Your plan will appear here after you click "Compose plan".</div>
        </div>
      </div>
    </section>

    <section style="margin-top:28px">
      <h2 style="margin:0 0 8px 0">How cohorts work</h2>
      <p class="muted-small">Sessions meet weekly for focused teaching, small-group reflection, and practical homework. You get a clear set of micro-steps rather than vague advice — community keeps you honest.</p>
    </section>

    <footer>
      <div>Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="margin-top:6px">Located in {{CITY}}, {{STATE}}</div>
    </footer>
  </main>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ items.forEach(i=>i.classList.add('reveal')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('reveal'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      items.forEach(i=>obs.observe(i));
    })();

    // Session Planner widget
    (function(){
      const $ = id=>document.getElementById(id);
      const build = $('build');
      const copyBtn = $('copy');
      const downloadBtn = $('download');
      const summary = $('summary');

      function makePlan(){
        const name = $('name').value.trim() || '[Name]';
        const focus = $('focus').value;
        const symptoms = $('symptoms').value.trim() || 'not specified';
        const time = $('time').value;
        const style = $('style').value;
        const lines = [];
        lines.push('Plan for: ' + name);
        lines.push('Focus: ' + focus + ' | Time per week: ' + time);
        lines.push('Key concerns: ' + symptoms);
        lines.push('Primary emphasis: ' + style);
        lines.push('');
        lines.push('Suggested first 4-week rhythm:');
        lines.push('- Week 1: baseline mapping — sleep log, meals, brief movement x3');
        lines.push('- Week 2: small change tied to cue (e.g., 10-minute evening wind-down)');
        lines.push('- Week 3: add one dietary pattern shift or focused breath practice');
        lines.push('- Week 4: consolidate with peer check-in and adjust plan');
        lines.push('');
        lines.push('Notes: This is educational content to guide your cohort intake. Not a substitute for individualized medical care.');
        return lines.join('\n');
      }

      build.addEventListener('click',()=>{
        const text = makePlan();
        summary.textContent = text;
      });

      copyBtn.addEventListener('click',async ()=>{
        const text = summary.textContent;
        try{ await navigator.clipboard.writeText(text); copyBtn.textContent = 'Copied'; setTimeout(()=>copyBtn.textContent='Copy summary',1400);}catch(e){ alert('Copy failed — your browser may restrict clipboard access.'); }
      });

      downloadBtn.addEventListener('click',()=>{
        const text = summary.textContent || makePlan();
        const blob = new Blob([text],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
      });
    })();
  </script>
</body>
</html>"} 
