<body>
  <svg class="svg-deco" width="420" height="420" viewBox="0 0 420 420" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <pattern id="q1" width="36" height="36" patternUnits="userSpaceOnUse">
        <rect width="18" height="18" fill="#f6fbf9"/>
        <path d="M2 14c4-6 10-6 14 0" stroke="#6ea07a" stroke-width="1.5" fill="none" stroke-linecap="round"/>
      </pattern>
    </defs>
    <rect width="420" height="420" fill="url(#q1)"/>
  </svg>

  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">A cohort-first, skills-centered pathway</div>
      </div>
