  <script>
    // reveal logic with reduced-motion respect
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const panels = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ panels.forEach(p=>p.classList.add('reveal')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('reveal'); io.unobserve(e.target); } });
      },{threshold:0.08});
      panels.forEach(p=>io.observe(p));
    })();

    // small session planner on this page
    (function(){
      const make = document.getElementById('make');
      const copyPlan = document.getElementById('copyPlan');
      const planOut = document.getElementById('planOut');
      function build(){
        const lens = document.getElementById('lens').value;
        const notes = document.getElementById('notes').value.trim() || '[one-line goal]';
        const lines = [];
        lines.push('Lens: ' + lens);
        lines.push('Goal: ' + notes);
        lines.push('Starter rhythm:');
        lines.push('- Day 1–7: track baseline (sleep, 1 meal log, energy)');
        lines.push('- Day 8–21: introduce a single micro-change tied to a daily cue');
        lines.push('- End of week 3: review with group checklist and adapt next step');
        lines.push('Note: Educational guidance. Not a replacement for medical advice.');
        return lines.join('\n');
      }
      make.addEventListener('click',()=>{ planOut.textContent = build(); });
      copyPlan.addEventListener('click',async ()=>{
        try{ await navigator.clipboard.writeText(planOut.textContent); copyPlan.textContent='Copied'; setTimeout(()=>copyPlan.textContent='Copy',1200);}catch(e){ alert('Unable to copy.'); }
      });
    })();
  </script>
